datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model User {
  id       Int    @id @default(autoincrement())
  username String @unique

  comments Comment[]
}

model Post {
  id    Int    @id @default(autoincrement())
  title String

  comments Comment[]
}

model Comment {
  id      Int    @id @default(autoincrement())
  content String

  post   Post @relation(fields: [postId], references: [id], onDelete: Cascade)
  postId Int

  author   User @relation(fields: [authorId], references: [id])
  authorId Int

  parent   Comment?  @relation("CommentReplies", fields: [parentId], references: [id], onDelete: Cascade)
  parentId Int?
  children Comment[] @relation("CommentReplies")
}

app nestedComments {
  wasp: {
    version: "^0.16.8"
  },
  title: "nested-comments",
  db: {
    seeds: [
      import { devSeed } from "@src/dbSeeds.js"
    ]
  }
}

route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

route PostRoute { path: "/post/:postId", to: PostPage }
page PostPage {
  component: import { PostPage } from "@src/PostPage"
}

query getPosts {
  fn: import { getPosts } from "@src/queries.js",
  entities: [Post]
}

query getCommentTree {
  fn: import { getCommentTree } from "@src/queries.js",
  entities: [Post, Comment]
}

action createComment {
  fn: import { createComment } from "@src/actions.js",
  entities: [Comment, Post, User]
}

action deleteComment {
  fn: import { deleteComment } from "@src/actions.js",
  entities: [Comment]
}

import { HttpError } from "wasp/server";

// getPosts: returns every post.
export const getPosts = async (args, context) => {
  const posts = await context.entities.Post.findMany({
    orderBy: { id: "asc" },
  });
  return posts;
};

// getCommentTree: given a postId, returns that post's comments as a nested tree.
export const getCommentTree = async ({ postId }, context) => {
  if (postId === undefined || postId === null) {
    throw new HttpError(400, "postId is required");
  }

  const post = await context.entities.Post.findUnique({
    where: { id: postId },
  });
  if (!post) {
    throw new HttpError(404, "Post not found");
  }

  const comments = await context.entities.Comment.findMany({
    where: { postId },
    include: { author: true },
    orderBy: { id: "asc" },
  });

  const nodeById = new Map();
  for (const comment of comments) {
    nodeById.set(comment.id, {
      id: comment.id,
      content: comment.content,
      authorUsername: comment.author.username,
      parentId: comment.parentId,
      children: [],
    });
  }

  const topLevel = [];
  for (const comment of comments) {
    const node = nodeById.get(comment.id);
    if (comment.parentId === null || comment.parentId === undefined) {
      topLevel.push(node);
    } else {
      const parentNode = nodeById.get(comment.parentId);
      if (parentNode) {
        parentNode.children.push(node);
      } else {
        // Parent not part of this result set (shouldn't normally happen).
        topLevel.push(node);
      }
    }
  }

  const sortTree = (nodes) => {
    nodes.sort((a, b) => a.id - b.id);
    for (const node of nodes) {
      sortTree(node.children);
    }
  };
  sortTree(topLevel);

  return topLevel;
};

import { HttpError } from "wasp/server";

// createComment: creates a comment on a post, authored by a user (looked up
// by username), optionally as a reply to an existing comment.
export const createComment = async (
  { postId, authorUsername, content, parentId },
  context
) => {
  if (postId === undefined || postId === null) {
    throw new HttpError(400, "postId is required");
  }
  if (!authorUsername) {
    throw new HttpError(400, "authorUsername is required");
  }
  if (!content) {
    throw new HttpError(400, "content is required");
  }

  const post = await context.entities.Post.findUnique({
    where: { id: postId },
  });
  if (!post) {
    throw new HttpError(404, "Post not found");
  }

  const author = await context.entities.User.findUnique({
    where: { username: authorUsername },
  });
  if (!author) {
    throw new HttpError(404, `User '${authorUsername}' not found`);
  }

  const resolvedParentId =
    parentId === undefined || parentId === null ? null : parentId;

  if (resolvedParentId !== null) {
    const parentComment = await context.entities.Comment.findUnique({
      where: { id: resolvedParentId },
    });
    if (!parentComment || parentComment.postId !== postId) {
      throw new HttpError(404, "Parent comment not found on this post");
    }
  }

  const comment = await context.entities.Comment.create({
    data: {
      content,
      post: { connect: { id: postId } },
      author: { connect: { id: author.id } },
      ...(resolvedParentId !== null
        ? { parent: { connect: { id: resolvedParentId } } }
        : {}),
    },
  });

  return comment;
};

// deleteComment: deletes a comment and all of its descendant replies (cascade).
export const deleteComment = async ({ commentId }, context) => {
  if (commentId === undefined || commentId === null) {
    throw new HttpError(400, "commentId is required");
  }

  const comment = await context.entities.Comment.findUnique({
    where: { id: commentId },
  });
  if (!comment) {
    throw new HttpError(404, "Comment not found");
  }

  // Collect the whole subtree (comment + all descendants) so we can delete
  // it explicitly, regardless of DB-level cascade behavior.
  const idsToDelete = [commentId];
  let frontier = [commentId];
  while (frontier.length > 0) {
    const children = await context.entities.Comment.findMany({
      where: { parentId: { in: frontier } },
      select: { id: true },
    });
    const childIds = children.map((c) => c.id);
    if (childIds.length === 0) break;
    idsToDelete.push(...childIds);
    frontier = childIds;
  }

  await context.entities.Comment.deleteMany({
    where: { id: { in: idsToDelete } },
  });

  return { deletedIds: idsToDelete };
};

// Idempotent dev seed: creates users `alice` and `bob`, and a post titled
// "Wasp Nested Comments". Safe to run more than once (uses upsert / findFirst
// checks so it never creates duplicates).
export const devSeed = async (prismaClient) => {
  const alice = await prismaClient.user.upsert({
    where: { username: "alice" },
    update: {},
    create: { username: "alice" },
  });

  const bob = await prismaClient.user.upsert({
    where: { username: "bob" },
    update: {},
    create: { username: "bob" },
  });

  const postTitle = "Wasp Nested Comments";
  let post = await prismaClient.post.findFirst({
    where: { title: postTitle },
  });
  if (!post) {
    post = await prismaClient.post.create({
      data: { title: postTitle },
    });
  }

  console.log("Seed complete:", {
    alice: alice.id,
    bob: bob.id,
    post: post.id,
  });
};

import { useState } from "react";
import { useParams } from "react-router-dom";
import { useQuery, getCommentTree, createComment, deleteComment } from "wasp/client/operations";

function ReplyForm({ postId, parentId, onDone }) {
  const [username, setUsername] = useState("alice");
  const [content, setContent] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!content.trim()) return;
    setSubmitting(true);
    setError(null);
    try {
      await createComment({
        postId,
        authorUsername: username,
        content,
        parentId: parentId ?? null,
      });
      setContent("");
      onDone();
    } catch (err) {
      setError(err.message || "Failed to create comment");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ margin: "8px 0" }}>
      <select value={username} onChange={(e) => setUsername(e.target.value)}>
        <option value="alice">alice</option>
        <option value="bob">bob</option>
      </select>{" "}
      <input
        type="text"
        placeholder={parentId ? "Write a reply..." : "Write a comment..."}
        value={content}
        onChange={(e) => setContent(e.target.value)}
        style={{ width: 300 }}
      />{" "}
      <button type="submit" disabled={submitting}>
        {parentId ? "Reply" : "Comment"}
      </button>
      {error && <div style={{ color: "red" }}>{error}</div>}
    </form>
  );
}

function CommentNode({ postId, node, onChanged }) {
  const [replying, setReplying] = useState(false);

  const handleDelete = async () => {
    await deleteComment({ commentId: node.id });
    onChanged();
  };

  return (
    <div style={{ marginLeft: 20, borderLeft: "1px solid #ddd", paddingLeft: 12, marginTop: 8 }}>
      <div>
        <strong>{node.authorUsername}</strong>: <span data-testid="comment-content">{node.content}</span>{" "}
        <button onClick={() => setReplying((r) => !r)}>Reply</button>{" "}
        <button onClick={handleDelete}>Delete</button>
      </div>
      {replying && (
        <ReplyForm
          postId={postId}
          parentId={node.id}
          onDone={() => {
            setReplying(false);
            onChanged();
          }}
        />
      )}
      {node.children.map((child) => (
        <CommentNode key={child.id} postId={postId} node={child} onChanged={onChanged} />
      ))}
    </div>
  );
}

export const PostPage = () => {
  const { postId } = useParams();
  const numericPostId = Number(postId);

  const {
    data: commentTree,
    isLoading,
    error,
    refetch,
  } = useQuery(getCommentTree, { postId: numericPostId });

  if (isLoading) return <div>Loading...</div>;
  if (error) return <div>Error: {error.message}</div>;

  return (
    <div className="container">
      <h2>Comments for post #{postId}</h2>

      <ReplyForm postId={numericPostId} parentId={null} onDone={refetch} />

      <div>
        {(commentTree ?? []).map((node) => (
          <CommentNode key={node.id} postId={numericPostId} node={node} onChanged={refetch} />
        ))}
      </div>
    </div>
  );
};

import { Link } from "react-router-dom";
import { useQuery, getPosts } from "wasp/client/operations";
import waspLogo from "./waspLogo.png";
import "./Main.css";

export const MainPage = () => {
  const { data: posts, isLoading, error } = useQuery(getPosts);

  return (
    <div className="container">
      <main>
        <div className="logo">
          <img src={waspLogo} alt="wasp" />
        </div>

        <h2 className="welcome-title">Threaded Comments Demo</h2>

        {isLoading && <p>Loading posts...</p>}
        {error && <p>Error: {error.message}</p>}

        <ul style={{ listStyle: "none", padding: 0 }}>
          {(posts ?? []).map((post) => (
            <li key={post.id}>
              <Link to={`/post/${post.id}`}>{post.title}</Link>
            </li>
          ))}
        </ul>
      </main>
    </div>
  );
};

